contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: deposit amount and a boolean whether to call withdraw
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // read credit before any operations via the public getter credit(address)
        uint creditBefore = c.credit(address(this));
        uint contractBalBefore = address(c).balance;

        // perform a deposit to the contract (this will increase credit and contract balance)
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        bool reverted = false;
        // attempt withdrawAll depending on parameter
        if (doWithdraw) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-values
        uint creditAfter = c.credit(address(this));
        uint contractBalAfter = address(c).balance;

        // If withdraw was attempted and did not revert, then credit for this address must be zero
        // and the contract's balance must have decreased by at least the difference in credit that was paid out.
        // Compute expected minimum decrease: if withdraw succeeded, at least the change in creditBefore->creditAfter
        // Note: avoid underflow by using comparisons rather than arithmetic that can underflow in assert.
        assert(
            // If no withdraw attempted, nothing required about credit change
            (!doWithdraw) ||
            // If withdraw attempted and reverted, no further conditions required
            (doWithdraw && reverted) ||
            // If withdraw attempted and did not revert: creditAfter == 0 and contractBalAfter <= contractBalBefore + depositAmount - (creditBefore + depositAmount)
            // Simplify: creditAfter == 0 and contractBalAfter <= contractBalBefore - creditBefore
            (doWithdraw && !reverted && creditAfter == 0 && contractBalAfter + creditBefore <= contractBalBefore)
        );
    }

    receive() external payable { }
}

