        uint contractBalBefore = address(c).balance;

        // perform deposit if requested
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        bool reverted = false;
        // attempt withdrawAll if requested
        if (doWithdraw) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // record balances after
        uint testBalAfter = address(this).balance;
        uint contractBalAfter = address(c).balance;

        // If withdrawAll was attempted and did NOT revert, then the contract's balance must have decreased by at least the depositAmount (money flowed back to this test),
        // and this test's balance must have increased by at least that amount.
        // Note: If depositAmount == 0, the inequalities allow equality.
        assert(
