contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an arbitrary deposit amount and then call withdrawAll.
    // The invariant: if withdrawAll does not revert, then c.credit(this) becomes 0
    // and address(c).balance is decreased by at most the deposited amount.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record balance of contract c before deposit
        uint beforeC = address(c).balance;

        // perform deposit of `amount` into c
        c.deposit{value: amount}();

        // record balance after deposit
        uint afterDepositC = address(c).balance;

        // now attempt withdrawAll; capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read the public credit mapping for this test contract (msg.sender for c is this contract)
        uint creditAfter = c.credit(address(this));

        // If withdrawAll succeeded (not reverted), then credit must be zero and
        // the contract's balance must have decreased by at most the earlier deposit amount.
        // (It should decrease exactly by the previous credit, which was <= amount, but we state
        // a slightly weaker property that is still meaningful and general.)
        assert(reverted || (creditAfter == 0 && afterDepositC >= address(c).balance && (afterDepositC - address(c).balance) <= amount));
    }

    // allow receiving ETH in case withdrawAll sends ETH back to this test contract
    receive() external payable {}
}

contract InvMutTest {
