        // initial observations
        uint beforeContractBalance = address(c).balance;
        // perform deposit into c
        c.deposit{value: depositAmount}();
        // observe recorded credit for this contract (auto getter: credit(address) is public)
        uint credited = c.credit(address(this));
        // credited should have increased by depositAmount (since starting from 0 for fresh c)
        // Now attempt withdrawAll and capture whether it reverted
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint afterContractBalance = address(c).balance;
        uint creditedAfter = c.credit(address(this));

        // General rule:
        // If withdrawAll succeeded, creditedAfter must be 0 and contract balance must have decreased by exactly credited
        // If withdrawAll reverted, contract balance and credited may be unchanged or changed only as allowed by revert behavior
        assert(
            (withdrew && creditedAfter == 0 && beforeContractBalance + depositAmount == afterContractBalance + credited)
            || (!withdrew)
        );
    }

    receive() external payable {}
}

