contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: amount to deposit (could be zero) and a flag whether to call withdraw
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // read initial observable values
        uint balBefore = address(c).balance;
        uint creditBefore = c.credit(address(this));

        // optionally deposit into c
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // read after-deposit values
        uint balAfterDeposit = address(c).balance;
        uint creditAfterDeposit = c.credit(address(this));

        // perform withdrawAll optionally, capturing whether it reverted
        bool withdrewReverted;
        if (doWithdraw) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = false;
        }

        // read final observable values
        uint balFinal = address(c).balance;
        uint creditFinal = c.credit(address(this));

        // General invariant: withdrawAll (if called) does not increase contract balance nor increase recorded credit for this caller.
        // Also ensure that deposit behaved as expected: after deposit, c.balance and credit did not decrease.
        assert(
            // deposit monotonicity: after deposit the contract balance and caller credit are at least as large as before deposit
            balAfterDeposit >= balBefore && creditAfterDeposit >= creditBefore
            &&
            // withdraw monotonicity: final contract balance no greater than after-deposit balance,
            // and final recorded credit no greater than after-deposit recorded credit
            balFinal <= balAfterDeposit && creditFinal <= creditAfterDeposit
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount this test will deposit into c (may be 0)
    // doWithdraw: whether to call withdrawAll after depositing
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // Observe contract balance before any actions
        uint balBefore = address(c).balance;

        // If requested, deposit Ether into c
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Observe balance immediately after deposit step
        uint balAfterDeposit = address(c).balance;

        // Now optionally call withdrawAll and record whether it reverted.
        bool withdrewReverted;
        if (doWithdraw) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = false;
        }

        // Observe final contract balance
        uint balFinal = address(c).balance;

        // General rule (single assert):
        // 1) The contract's balance never increases as a result of the withdraw step:
        //    balFinal <= balAfterDeposit
        // 2) The balance after deposit is at least the balance before deposit (deposit cannot reduce contract balance):
        //    balAfterDeposit >= balBefore
        // 3) If withdrawAll reverted, then the test contract's external balance should not have decreased due to the attempted withdraw (i.e., revert prevented Ether leaving c to this contract):
        //    if withdrewReverted then address(this).balance >= (address(this).balance - 0) which is tautological in EVM; to make a usable observable check we require that when withdraw reverted, the final contract balance is equal to its balance after deposit (no Ether left c on revert).
        // Combining: balAfterDeposit >= balBefore && balFinal <= balAfterDeposit && (withdrewReverted ? balFinal == balAfterDeposit : true)
        assert(balAfterDeposit >= balBefore && balFinal <= balAfterDeposit && (!withdrewReverted || balFinal == balAfterDeposit));
    }

    // Accept Ether if c sends it back
    receive() external payable {}
}

