contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two amounts: initialDeposit to set up credit, and laterDeposit to test withdrawability after calling withdrawAll.
    // The function is payable to allow sending Ether when calling c.deposit.
    function run(uint initialDeposit, uint laterDeposit) public payable {
        require(address(this).balance >= initialDeposit + laterDeposit, "need funds");
        // Setup: deposit initialDeposit into c from this contract
        if (initialDeposit > 0) {
            c.deposit{value: initialDeposit}();
        }

        // Call withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the withdrawAll attempt, make a later deposit of laterDeposit
        if (laterDeposit > 0) {
            c.deposit{value: laterDeposit}();
        }

        // Now attempt to withdrawAll again and observe whether it succeeds and how much can be removed.
        // We cannot directly observe the returned amount, but we can observe address(c).balance change.
        uint balBefore = address(c).balance;
        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint balAfter = address(c).balance;

        // The general invariant we assert: any successful second withdraw can reduce c's balance by at most laterDeposit.
        // If the second withdraw reverted then no reduction happened; if it succeeded then reduction <= laterDeposit.
        // This ensures the first withdrawAll did not create extra withdrawable credit beyond what we explicitly deposited later.
        if (secondReverted) {
            assert(balAfter == balBefore);
        } else {
            // balBefore - balAfter is how much Ether left c and was given to this contract
            assert(balBefore - balAfter <= laterDeposit);
        }
    }

    receive() external payable {}
}

