        } catch {
            firstReverted = true;
        }

        // Make a later deposit of laterDeposit
        if (laterDeposit > 0) {
            c.deposit{value: laterDeposit}();
        }

        // Observe c's balance before the second withdrawAll
        uint balBefore = address(c).balance;

        // Second attempt to withdrawAll; record whether it reverted
        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
