contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: firstDeposit sets up initial credit, extraDeposit optionally increases credit later.
    function run(uint firstDeposit, uint extraDeposit) public payable {
        // ensure the test contract has enough Ether to perform the deposits
        require(address(this).balance >= firstDeposit + extraDeposit, "need funds");

        // Setup: make an initial deposit (may be zero)
        if (firstDeposit > 0) {
            c.deposit{value: firstDeposit}();
        }

        // Optionally make an extra deposit (may be zero)
        if (extraDeposit > 0) {
            c.deposit{value: extraDeposit}();
        }

        // Record observable state before withdraw
        uint balBefore = address(c).balance;

        // Attempt withdrawAll and record whether it reverted
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // After the call, observe the contract balance and this contract's apparent credit via making a small deposit and immediate withdraw
        uint balAfter = address(c).balance;

        // To observe the remaining credit without directly reading private state, deposit 0 and then try withdrawAll to see what can be taken.
        // First, make no-op deposit if needed (deposit of 0 is allowed): call deposit{value:0}()
        c.deposit{value:0}();

        // Now attempt a subsequent withdrawAll to see what remains withdrawable; capture whether it succeeds
        bool secondWithdrew;
        try c.withdrawAll() {
            secondWithdrew = true;
        } catch {
            secondWithdrew = false;
        }

        // If the first withdraw succeeded, then the contract must have cleared this caller's credit (so the subsequent withdraw should not be able to take any additional funds attributable to earlier deposits).
        // We express this by: if first withdraw succeeded then the second withdraw cannot decrease address(c).balance further because the caller's credit was set to zero.
        // So: if withdrew == true then balAfter <= balBefore and secondWithdrew must be false (no further funds withdrawable without new deposits).
        assert(withdrew ? (balAfter <= balBefore && secondWithdrew == false) : true);
    }

    // receive to accept Ether sent by C when withdraw succeeds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a single deposit amount to set up credit, then call withdrawAll once and observe effects.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "need funds");

        // Setup: make a deposit to create credit for this contract (may be zero)
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        } else {
            // still call deposit with 0 to leave observable state consistent
            c.deposit{value: 0}();
        }

        // Record contract balance before withdraw
        uint balBefore = address(c).balance;

        // Attempt first withdrawAll and record whether it reverted
        bool firstSucceeded;
        try c.withdrawAll() {
            firstSucceeded = true;
        } catch {
            firstSucceeded = false;
        }

        // Record contract balance after first withdraw attempt
        uint balAfter = address(c).balance;

        // Make a noop deposit to ensure we can attempt a second withdrawAll
        c.deposit{value: 0}();

        // Attempt second withdrawAll to see if any remaining credit can be taken
        bool secondSucceeded;
        try c.withdrawAll() {
            secondSucceeded = true;
        } catch {
            secondSucceeded = false;
        }

        // General rule:
        // If the first withdraw succeeded then:
        // 1) address(c).balance decreased by at least depositAmount (i.e., balAfter <= balBefore and the decrease is <= balBefore and at least depositAmount was removed),
        //    expressed as balBefore - balAfter >= depositAmount without underflow because we only assert when firstSucceeded.
        // 2) the subsequent withdraw cannot succeed (credit cleared), so secondSucceeded == false.
        if (firstSucceeded) {
            assert(balBefore >= balAfter && balBefore - balAfter >= depositAmount && secondSucceeded == false);
        } else {
            // If first failed, we assert nothing about balances beyond allowing any outcome; still must reach an assert.
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
