    // Single public function with all logic and exactly one assert at the end.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "need funds");

        // Make an initial deposit (may be zero) to create credit for this contract.
        c.deposit{value: depositAmount}();

        // Record contract balance before the first withdraw
        uint balBefore = address(c).balance;

        // Attempt first withdrawAll and record whether it reverted
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
