contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to deposit, then call withdrawAll and assert the invariant.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record contract balance before any operations
        uint beforeContractBalance = address(c).balance;

        // perform a deposit to set up a non-zero credit for this caller
        c.deposit{value: depositAmount}();

        // read observable credit after deposit by attempting to infer via behavior:
        // There's no public getter for credit, so we observe effects: record balance before withdraw
        uint midContractBalance = address(c).balance;

        bool reverted;
        // call withdrawAll and catch revert
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBalance = address(c).balance;

        // General rule: if withdrawAll succeeded then contract balance did not increase and caller's observable credit is zero afterward.
        // We cannot read private credit, but we can assert that if withdraw did not revert then contract balance <= midContractBalance
        // and if withdraw did not revert then after performing a zero-value deposit and another withdraw, that second withdraw cannot gain more Ether from the contract (i.e., contract balance does not decrease further as a result of it).

        if (!reverted) {
            // withdraw was successful: contract balance must not have increased compared to before the withdraw
            // and must be <= midContractBalance (which included our deposit)
            assert(afterContractBalance <= midContractBalance);

            // Additionally, observable credit for this caller should be cleared: performing a zero deposit then withdrawAll should not further decrease contract balance.
            uint balBeforeSecond = address(c).balance;
            c.deposit{value: 0}();
            bool reverted2;
            try c.withdrawAll() {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            uint balAfterSecond = address(c).balance;
            // If the second withdraw did not revert, it must not withdraw any Ether (since credit should be zero), so balance must stay the same
            if (!reverted2) {
                assert(balAfterSecond == balBeforeSecond);
            }
        } else {
            // if it reverted we still require that contract balance did not increase compared to before depositing (sanity)
            // This avoids trivial constant asserts; relate beforeContractBalance and afterContractBalance
            assert(afterContractBalance >= beforeContractBalance);
        }
    }

    receive() external payable {}
}
